#!/usr/bin/env python3
"""Generate native/include/hle_import_names.h from config/hle_imports.json."""

from __future__ import annotations

import json
from pathlib import Path

PROJECT = Path(__file__).resolve().parents[1]
names = json.loads((PROJECT / "config/hle_imports.json").read_text(encoding="utf-8"))

lines = [
    "// GENERATED by tools/gen_import_names.py — DO NOT EDIT.",
    "#pragma once",
    "",
    f"inline constexpr const char* kHLEImportNames[] = {{",
]
for name in names:
    lines.append(f'    "{name}",')
lines.append("};")
lines.append(f"inline constexpr int kHLEImportCount = {len(names)};")

out = PROJECT / "native/include/hle_import_names.h"
out.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"generated {len(names)} names -> {out.relative_to(PROJECT)}")
